var a=`0862-rasgulla`;var t=`world-0862`;var l=`IN`;var s=`south-asia`;var n=8;var o=174;var r={en:`Rasgulla`,ua:`Расгулла`};var u={en:`Rasgulla is a India dish made with whole cow milk, lemon juice, semolina flour. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Расгулла, страва кухні країни Індія. Основні складники: цільне коров'яче молоко, лимонний сік, семоліна. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var d=[{en:`Heat milk almost to a boil, add lemon juice to separate curds, then strain through clean cheesecloth; rinse and squeeze carefully.`,ua:`Нагрійте молоко майже до кипіння, додайте лимонний сік для відділення згустку, процідіть крізь чисту тканину, промийте та обережно відіжміть.`,t:[`boiling`],m:8,i:[[`whole-cow-milk`,1500,`ml`],[`lemon-juice`,75,`ml`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:30,i:[]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:12,i:[[`semolina-flour`,15,`g`]]},{en:`Prepare a light sugar syrup separately; it must be at a gentle boil before adding the cheese balls.`,ua:`Окремо приготуйте легкий цукровий сироп; перед зануренням сирних кульок він має ледь кипіти.`,t:[`reducing-sauce`],m:12,i:[[`white-granulated-sugar`,340,`g`],[`water`,1050,`ml`]]},{en:`Simmer the kneaded cheese balls in sugar syrup with space to expand; they should become spongy and double in size.`,ua:`Варіть вимішані сирні кульки в цукровому сиропі з місцем для збільшення: вони мають стати пористими й удвічі більшими.`,t:[`poaching`],m:22,i:[]},{en:`Cool the prepared ingredients promptly, then refrigerate for about 90 minutes until properly chilled.`,ua:`Швидко охолодіть підготовлені складники, потім поставте в холодильник приблизно на 90 хвилин.`,t:[`rapid-chilling`],m:90,i:[]}];var h={slug:a,id:t,country:`IN`,region:s,servings:8,minutes:174,title:r,text:u,steps:d};export{l as country,h as default,t as id,o as minutes,s as region,n as servings,a as slug,d as steps,u as text,r as title};